// FILE: /home/zero_rom/zero2np/src/system/os/system.c
//
// OS-layer system bring-up and per-frame back-end for the zero2np engine.
//
//   * Boot          - InitSystemON() lays out the EE heaps, brings up the IOP
//                     (ee_iopInit), the CD data table, the exception handler,
//                     graphics, the V-blank sema/callback, the pad, the
//                     performance counter and the system sound bank.
//   * Memory        - systemGetMem()/systemFreeMem() wrap the system heap;
//                     GetSystemHeapWrkP() exposes it.
//   * Video         - ChangeVideoMode()/SetGsResetGraph()/SetPCRTC()/
//                     SetFrameBuffer()/SetDisplayPos() drive the GS CRTC and
//                     the double display/draw buffers in 'gdb'.
//   * Per-frame     - vfunc() waits out the V-blank count, swaps the draw
//                     buffer and re-arms the CRTC; SendDMAMain()/SendDMASub()
//                     kick the VIF1 channel.
//   * Services      - GetNowClock() (RTC), the SystemBank* sound-bank wrappers
//                     and the language getters/setters.
//
// Reconstructed from the Feb 6 2004 prototype (SLES_523.84).

#include "system.h"                 // system API + the fixed EE memory map

#include <eekernel.h>               // CreateSema/WaitSema/PollSema/iSignalSema,
                                    // AddDmacHandler/EnableDmac, FlushCache, EI/SYNC
#include <eeregs.h>                 // REG_RCNT1_COUNT, REG_GS_* CRTC registers
#include <libcdvd.h>                // sceCdReadClock / sceCdCLOCK
#include <libdma.h>                 // sceDma* channel/env API
#include <libgraph.h>               // sceGs* (reset / dbuff / sync / CRTC)
#include <libpad.h>                 // pad bring-up
#include <libscf.h>                 // sceScfGetLanguage
#include <sifrpc.h>                 // IOP services

#include "../../sdk/sce_gs.h"               // sceGsDBuff / sceGsDrawEnv1 / tGS_* register file
#include "../../graphics/graph3d/g3dGsWrapper.h" // g3dGs* wrappers
#include "../../graphics/graph3d/g3dDebug.h" // g3ddbgInfinitePrintConsole

#include "heapctrl.h"               // HEAP_WRK / heapCtrlInit / heapCtrlMalloc / heapCtrlFree
#include "mem_util.h"               // mem_utilInit
#include "mem_dbg.h"                // mem_dbgInit
#include "../../common/ol_load.h"   // ol_loadHeapInit (out-game load heap)
#include "../eeiop/ee_iop.h"        // EEIOP_DEF / ee_iopInit
#include "eecdvd.h"                 // LoadReq / FileLoadReqEE / GetFileSize
#include "../eeiop/cddat.h"         // cddatInit + CD_DAT_TBL / FNAME_DAT tables
#include "../../common/variable.h"  // sys_wrk / opt_wrk (SYS_WRK / OPTION_WRK)
#include "eeException.h"            // eeexception* / iopexception* / IOPEXCEPTIONCREATIONDATA
#include "../eeiop/snd3d.h"         // snd3DSetEnvironment / SND_3D_ENV / SND_3D_SET
#include "../eeiop/sndbank.h"       // SndBank* sound-bank API
#include "../../graphics/dmaVif1.h" // dmaVif1CheckDMA / dmaVif1Kick
#include "../../graphics/graph2d/graph2d.h" // InitGraph2dEFrame / DrawPerformanceCounter2
#include "../../miopan/miopan_profiler.h"
#include "../../miopan/os/miopan_pacing.h" // host V-blank wait override (measurement harness)
#include "../../miopan/rendering/miopan_renderer.h"
#include "../pad/pad.h"             // InitPad / PadAnalog*
#include "../../debug/zero2_debug.h" // DebugInit
#include "../../ingame/map/MapSave.h" // MapSavePushFirstDat
#include "../../outgame/mission_sel.h" // MissionSelTblInit

// ──────────────────────────────────────────────────────────────────────
// Statics / file-scope globals

static HEAP_WRK system_heap_wrk;            // bss   4bc620 : the engine's master heap
static int      SYSTEM_VBLANK_WAIT_NUM = 2;     // sdata 3f4618 : V-blanks to wait per frame
static int      vblank_sema;                // sbss  3f4fb8 : V-blank signalling sema
static int      draw_perf_count;            // sbss  3f4fbc : RCNT1 snapshot at draw start

sceGsDBuff   gdb;                           // data  35e3b0 : double display/draw buffer set
// data 34fea0 : 3D-sound distance environment.  Handed to
// snd3DSetEnvironment() at boot and again at the top of every frame, so it
// permanently replaces snd_3d.c's own defaults -- this table, not that one, is
// what the game actually hears.  Values are verbatim from the ROM's .data;
// `front` and `side` are one ulp below the round decimal, which is EE GCC's
// literal truncation (see 0.8f / 0.1f), while the other four round exactly.
SND_3D_ENV   s3d_env =
{
    0.79999995f,                    // front         (0x3f4ccccc)
    0.099999994f,                   // side          (0x3dcccccc)
    0.7f,                           // back          (0x3f333333)
    0.03f,                          // vol_min       (0x3cf5c28f)
    16.0f,                          // farthest_dist (0x41800000)
    2.5f                            // nearest_dist  (0x40200000)
};
void        *pdrawenv;                      // sdata 3f4628 : draw env for the current frame
int          system_sound_bank_id;          // sdata 3f462c : handle for the system SE bank

// sys_wrk / opt_wrk (and the SYS_WRK / OPTION_WRK types) come from
// common/variable.h; see the #include below.

// performance counter object (FrameInit() is a method on it)
#include "../../debug/zero2_perf.h"          // C_ZERO2_PERF_CNT c_zero2_perf_cnt (sdata 3f4908)
#include "../../miopan/miopan_memory.h"      // host backing for fixed EE addresses

