static void InitSysWrk(void);
static int  v_callback(int i);
static void InitGraphics(void);
static void InitVBlank(void);
static void vfunc(void);

// the per-TU fixed_array<> template instances (_fixed_array_assert /
// _fixed_array_verifyrange<T>) are emitted here by the compiler; see
// "ctl/fixed_array.h" for their definitions.

// ──────────────────────────────────────────────────────────────────────
// System heap

HEAP_WRK *GetSystemHeapWrkP(void)
{
    return &system_heap_wrk;
}

void SetVBlankWaitNum(int iWaitNum)
{
    /* PORT: only on a real change.  MioPan_RendererSetPresentInterval() zeroes
     * the FPS window and calls MioPan_ProfilerReset(), and PlayMovie() calls
     * this every frame of a movie with the same 1 -- which reset the profiler
     * once per frame and left it with nothing to average. */
    if (SYSTEM_VBLANK_WAIT_NUM == iWaitNum)
    {
        return;
    }

    SYSTEM_VBLANK_WAIT_NUM = iWaitNum;
    MioPan_RendererSetPresentInterval(1);
}

void *systemGetMem(int size)
{
    return heapCtrlMalloc(&system_heap_wrk, size);
}

void systemFreeMem(void *adrs)
{
    heapCtrlFree(&system_heap_wrk, adrs);
}

// ──────────────────────────────────────────────────────────────────────
// VIF1 channel-1 DMA-completion handler (installed via AddDmacHandler).  It
// snapshots the RCNT1 elapsed-VIF timer; the int return is the handler ABI.

int GetVifEndTimer(int ch)
{
    draw_perf_count = REG_RCNT1_COUNT;
    SYNC(0);
    EI();

    return 0;
}

// ──────────────────────────────────────────────────────────────────────
// Exception handling: enable EE syscall/breakpoint exceptions, bring up the
// EE-side exception module, then load the IOP panic-handler IRX.

static void _InitException(void)
{
    IOPEXCEPTIONCREATIONDATA iopeCD;

    eeexceptionEnableExcCode(PS2E_SYSCALL, 0);
    eeexceptionEnableExcCode(PS2E_BREAKPOINT, 0);
    eeexceptionInitialize();
    g3ddbgInfinitePrintConsole(1);

    iopeCD.pModuleName = "cdrom0:\\PANICSYS.IRX;1";
    iopexceptionInitialize(&iopeCD);
}

// ──────────────────────────────────────────────────────────────────────
// One-time engine boot.  Carves up EE main memory into the system / mem_util /
// model / debug heaps, then brings every subsystem online in dependency order.

void InitSystemON(void)
{
    HEAP_WRK *wrk;
    EEIOP_DEF def;

    MioPan_InitPs2Memory();

    // Heaps (bases/sizes are the constants from the EE memory map).
    wrk = GetSystemHeapWrkP();
    heapCtrlInit(wrk, (void *)HEAP_AREA_ADDR, 0xc8000);
    mem_utilInit((void *)MEM_UTIL_HEAP_ADDR, 0x2b1400);
    ol_loadHeapInit((void *)MODEL_HEAP_ADDR, 0x7a8000);
    mem_dbgInit((void *)0x3100000, 0x1000000);

    // IOP definition table.  These field values are the static template the
    // compiler copied in from rdata @ 0x3c84c0 (recovered from the ELF).
    def.malloc64                 = systemGetMem;
    def.free64                   = systemFreeMem;
    def.command_send_buffer_size = 0;
    def.iop_def_module           = "cdrom0:\\IOPRP280.IMG;1";
    def.hil_file_name            = "cdrom0:\\ZERO2IRX.HIL;1";
    def.dil_file_name            = "cdrom0:\\ZERO2IRX.DIL;1";
    def.media                    = 2;
    def.file_load_wrk_num        = 50;
    def.snd_bank_wrk_num         = 30;
    def.stream_auto_wrk_num      = 10;
    def.auto_bd_wrk_num          = 5;
    def.snd_stream_load_priority = 1;
    def.snd_bank_load_priority   = 6;
    def.cmp_use_flg              = 1;
    def.rom_boot                 = 1;
    ee_iopInit(&def);

    // CD data table: 0x118b files, paths rooted at "host0:".
    cddatInit("IMG_BD.BIN", "host0:", filename_dat, filename_path,
              cd_dat_tbl, file_ext_tbl, 0x118b);

    _InitException();
    snd3DSetEnvironment(&s3d_env);
    InitSysWrk();
    InitGraphics();
    InitVBlank();
    SetDefaultKeyType();
    InitPad();
    PadAnalogInit();
    c_zero2_perf_cnt.FrameInit();

    AddDmacHandler(1, GetVifEndTimer, -1);
    EnableDmac(1);

    SystemBankSetup();
    MapSavePushFirstDat();
    MissionSelTblInit();
    DebugInit();
}

// ──────────────────────────────────────────────────────────────────────
// Initialise the top-level system work block: RTC, soft-reset counter, the
// default video mode (PAL) and language.

static void InitSysWrk(void)
{
    GetNowClock(&sys_wrk.rtc);

    sys_wrk.sreset_count = 0;
    sys_wrk.video_mode   = VIDEO_MODE_NTSCU; /* Changed the default from 3 so it may use 60Hz */
    sys_wrk.language     = 0;
}

// ──────────────────────────────────────────────────────────────────────
// V-blank callback: signal the V-blank sema (interrupt context).

static int v_callback(int i)
{
    iSignalSema(vblank_sema);
    SYNC(0);
    EI();

    return 0;
}

// ──────────────────────────────────────────────────────────────────────
// Bring up the VIF/VU/GS path and prime both halves of the display buffer.

static void InitGraphics(void)
{
    sceDmaEnv env;

    sceDmaReset(1);
    sceGsResetPath();
    sceDevVif0Reset();
    sceDevVu0Reset();
    SetGsResetGraph(0);

    sceDmaGetEnv(&env);
    env.notify = 4;
    sceDmaPutEnv(&env);

    SetFrameBuffer();
    SetDisplayPos();
    FlushCache(0);
    sceGsSyncV(0);

    g3dGsPutDrawEnv(&gdb.giftag0);
    g3dGsSyncPath(0, 0);
    g3dGsPutDrawEnv(&gdb.giftag1);
    g3dGsSyncPath(0, 0);
}

// ──────────────────────────────────────────────────────────────────────
// Create the V-blank counting sema and install the V-blank callback.

static void InitVBlank(void)
{
    SemaParam semap;

    semap.initCount = 0;
    semap.maxCount  = SYSTEM_VBLANK_WAIT_NUM;
    vblank_sema     = CreateSema(&semap);

    /*
     * The game loop itself waits SYSTEM_VBLANK_WAIT_NUM ticks below.  Present
     * every completed game frame instead of applying the interval a second
     * time in the renderer.
     */
    MioPan_RendererSetPresentInterval(1);
    SystemSetVCallback();
}

// ──────────────────────────────────────────────────────────────────────
// Switch video mode (NTSC '\x02' / PAL '\x03').  Spin the frame loop a few
// times so the swap lands cleanly, then re-init the DMA/GS path and V-blank.

void ChangeVideoMode(u_char mode)
{
    int i;
    sceDmaEnv env;

    if (((u_char)(mode - 2) < 2) && (sys_wrk.video_mode != mode))
    {
        for (i = 9; -1 < i; i--)
        {
            sys_wrk.video_mode = mode;
            vfunc();
        }

        sceDmaReset(1);
        sceDevVif0Reset();
        sceDevVu0Reset();
        SetGsResetGraph(0);

        sceDmaGetEnv(&env);
        env.notify = 4;
        sceDmaPutEnv(&env);

        SetDisplayPos();
        InitVBlank();
        AddDmacHandler(1, GetVifEndTimer, -1);
        EnableDmac(1);

        for (i = 19; -1 < i; i--)
        {
            vfunc();
        }
    }
}

// ──────────────────────────────────────────────────────────────────────
// True when running in PAL mode.

int GetPALMode(void)
{
    return (sys_wrk.video_mode == VIDEO_MODE_PAL);
}

// ──────────────────────────────────────────────────────────────────────
// Install v_callback() as the GS V-blank callback.

void SystemSetVCallback(void)
{
    sceGsSyncVCallback(v_callback);
}

// ──────────────────────────────────────────────────────────────────────
// Build the default double display/draw buffer set, then patch the frame /
// z-buffer base pointers (FBP/ZBP) and clear-colour for both halves.

void SetFrameBuffer(void)
{
    sceGsSetDefDBuff(&gdb, SCE_GS_PSMCT32, 640, 448, 2, 10, 1);

    gdb.disp[0].dispfb.FBP = 0;
    gdb.disp[1].dispfb.FBP = 140;

    gdb.draw0.frame1.FBP = 140;
    gdb.draw0.zbuf1.ZBP  = 280;
    gdb.draw1.frame1.FBP = 140;
    gdb.draw1.zbuf1.ZBP  = 280;

    gdb.clear0.rgbaq.R = 0;
    gdb.clear0.rgbaq.G = 0;
    gdb.clear0.rgbaq.B = 0;
    gdb.clear1.rgbaq.R = 0;
    gdb.clear1.rgbaq.G = 0;
    gdb.clear1.rgbaq.B = 0;
}

// ──────────────────────────────────────────────────────────────────────
// Position the displayed image (DX/DY) for the current video mode.

void SetDisplayPos(void)
{
    int dx;
    int dy;

    if (sys_wrk.video_mode == VIDEO_MODE_PAL)            // PAL
    {
        dx = 656;
        dy = 104;
    }
    else
    {
        if (VIDEO_MODE_PAL < sys_wrk.video_mode)
        {
            return;
        }

        if (sys_wrk.video_mode != VIDEO_MODE_NTSCU)        // NTSC
        {
            return;
        }

        dx = 636;
        dy = 50;
    }

    gdb.disp[1].display.DX = dx;
    gdb.disp[1].display.DY = dy;
    gdb.disp[0].display.DX = dx;
    gdb.disp[0].display.DY = dy;
}

// ──────────────────────────────────────────────────────────────────────
// Reset the GS for the current video mode.

void SetGsResetGraph(int n)
{
    if (sys_wrk.video_mode == VIDEO_MODE_PAL)
    {
        sceGsResetGraph(n, SCE_GS_INTERLACE, SCE_GS_PAL, SCE_GS_FRAME);
        return;
    }

    if (sys_wrk.video_mode < VIDEO_MODE_MAX)
    {
        if (sys_wrk.video_mode == VIDEO_MODE_NTSCU)
        {
            sceGsResetGraph(n, SCE_GS_INTERLACE, SCE_GS_NTSC, SCE_GS_FRAME);
            return;
        }
    }
    else if (sys_wrk.video_mode == 0x50)
    {
        sceGsResetGraph(n, SCE_GS_INTERLACE, SCE_GS_DTV480P, SCE_GS_FRAME);
    }
}

// ──────────────────────────────────────────────────────────────────────
// Program the PCRTC display registers directly for the given frame parity.
// The packed DISPLAY/DISPFB values are the mode-specific CRTC constants; the
// frame parity toggles the DISPFB base by 0x8c (alternating field buffers).

void SetPCRTC(int frame)
{
    u_long fbp;

    REG_GS_PMODE  = 0x8023;
    REG_GS_SMODE2 = 1;

    if (sys_wrk.video_mode == VIDEO_MODE_PAL)            // PAL
    {
        fbp = (frame & 1) * 0x8c;
        REG_GS_DISPLAY1 = SCE_GS_SET_DISPLAY(656, 104, 3, 0, 2559, 447);
        REG_GS_DISPFB1  = fbp | 0x9400;
        REG_GS_DISPLAY2 = SCE_GS_SET_DISPLAY(656, 104, 3, 0, 2559, 446);;
        REG_GS_DISPFB2  = fbp | 0x80000009400;
        return;
    }

    if ((sys_wrk.video_mode < VIDEO_MODE_MAX) && (sys_wrk.video_mode == VIDEO_MODE_NTSCU))  // NTSC
    {
        fbp = (frame & 1) * 0x8c;
        REG_GS_DISPLAY1 = SCE_GS_SET_DISPLAY(636, 50, 3, 0, 2559, 447);
        REG_GS_DISPFB1  = fbp | 0x9400;
        REG_GS_DISPLAY2 = SCE_GS_SET_DISPLAY(636, 50, 3, 0, 2559, 446);
        REG_GS_DISPFB2  = fbp | 0x80000009400;
    }
}

// ──────────────────────────────────────────────────────────────────────
// Read the real-time clock.  On failure, zero it and flag .pad.

void GetNowClock(sceCdCLOCK *nc)
{
    memset(nc, 0, sizeof(sceCdCLOCK));

    if (sceCdReadClock(nc) == 0)
    {
        memset(nc, 0, sizeof(sceCdCLOCK));
        nc->pad = 1;
    }
}

// ──────────────────────────────────────────────────────────────────────
// The per-frame back end: refresh the 3D-sound environment, wait out the
// configured number of V-blanks, advance the frame counter, swap the double
// buffer and re-arm the PCRTC for the new frame.

static void vfunc(void)
{
    int i;
    int remain;
    int count;
    int wait_num;
    int wait_calls;
    uint64_t wait_ticks;

    snd3DSetEnvironment(&s3d_env);

    /* PORT: the ROM reads SYSTEM_VBLANK_WAIT_NUM here directly.  The override
     * is a host measurement harness -- see miopan_pacing.h -- and returns the
     * game's own value whenever it is off, which is always unless somebody has
     * gone into the profiler menu.  It is checked per frame rather than latched
     * because movie.c rewrites the game's value every frame of a movie. */
    wait_num = MioPan_ResolveVBlankWait(SYSTEM_VBLANK_WAIT_NUM);
    count = 0;
    wait_calls = 0;
    wait_ticks = 0;
    g3dGsSyncPath(0, 0);

    while (PollSema(vblank_sema) != -1)
    {
        count++;
    }

    remain = (wait_num - count) - 1;
    if (0 < remain)
    {
        do
        {
            remain--;
            uint64_t wait_start = MioPan_ProfilerNow();
            WaitSema(vblank_sema);
            wait_ticks += MioPan_ProfilerNow() - wait_start;
            wait_calls++;
        } while (remain != 0);
    }
    uint64_t wait_start = MioPan_ProfilerNow();
    WaitSema(vblank_sema);
    wait_ticks += MioPan_ProfilerNow() - wait_start;
    wait_calls++;

    MioPan_ProfilerRecordVblankPacing(wait_ticks, count, wait_calls, wait_num);

    c_zero2_perf_cnt.FrameInit();
    sys_wrk.count++;

    FlushCache(0);
    g3dGsSwapDBuff(&gdb, (int)sys_wrk.count);
    SetPCRTC((int)sys_wrk.count);

    pdrawenv = &gdb.draw0;
    if ((sys_wrk.count & 1) == 0)
    {
        pdrawenv = &gdb.draw1;
    }
}

// ──────────────────────────────────────────────────────────────────────
// Fire a one-shot DMA packet down the VIF1 channel (channel 1) and wait for
// it to drain.

void SendDMASub(Q_WORDDATA *packet_buf)
{
    sceDmaChan *DmaVif;

    DmaVif = sceDmaGetChan(1);
    DmaVif->chcr.TTE = 1;               // tag-transfer enable (CHCR bit 6)
    FlushCache(0);

    sceDmaSend(DmaVif, (void *)((uintptr_t)packet_buf & 0xfffffff));
    sceDmaSync(DmaVif, 0, 0);
    g3dGsSyncPath(0, 0);
}

// ──────────────────────────────────────────────────────────────────────
// The per-frame main DMA kick: finish the previous transfer, account for it
// in the performance counter, run the frame back end and kick the next one.

void SendDMAMain(void)
{
    dmaVif1CheckDMA();
    g3dGsSyncPath(0, 0);
    DrawPerformanceCounter2(draw_perf_count);
    vfunc();
    dmaVif1Kick();
    MioPan_RendererEndFrame();
    InitGraph2dEFrame();
}

// ──────────────────────────────────────────────────────────────────────
// Return the draw env for the given frame parity.

sceGsDrawEnv1 *GetDrawEnv(int id)
{
    sceGsDrawEnv1 *pRetEnv;

    if ((id & 1) == 0)
    {
        pRetEnv = &gdb.draw0;
    }
    else
    {
        pRetEnv = &gdb.draw1;
    }

    return pRetEnv;
}

// ──────────────────────────────────────────────────────────────────────
// System sound-bank wrappers (SE bank 0xcf9 / header 0xcf8).

void SystemBankSetup(void)
{
    system_sound_bank_id = SndBankNew(BASE_SYS_BD_BD, BASE_SYS_BD_HXD, -1);
}

int SystemBankIsReady(void)
{
    return SndBankIsReady(system_sound_bank_id);
}

int SystemBankPlay(int no, int effect, int loop, int fade_time, SND_3D_SET *s3d, int vol, int pitch)
{
    return SndBankPlay(system_sound_bank_id, no, effect, loop, vol, pitch, fade_time, s3d);
}

void SystemBankRelease(void)
{
    SndBankRelease(system_sound_bank_id);
    system_sound_bank_id = -1;
}

int SystemBankIsLoopSnd(int no)
{
    return SndBankIsLoopSnd(system_sound_bank_id, no);
}

// ──────────────────────────────────────────────────────────────────────
// Language getters / setters.

void SetLanguage(u_char language)
{
    sys_wrk.language = language;
}

u_char GetLanguage(void)
{
    return sys_wrk.language;
}

// Map the console's configured language (SCF) onto the game's language enum.
u_char GetSystemLanguage(void)
{
    u_char lang = 0;

    // Map the SCF system-config language id onto the game's language index.
    switch (sceScfGetLanguage())
    {
        default:
    case SCE_ENGLISH_LANGUAGE: 
        {
            lang = 0;
            break;
        }
    case SCE_FRENCH_LANGUAGE:
        {
            lang = 1;
            break;
        }
    case SCE_SPANISH_LANGUAGE:
        {
            lang = 3;
            break;
        }
    case SCE_GERMAN_LANGUAGE:
        {
            lang = 2;
            break;
        }
    case SCE_ITALIAN_LANGUAGE:
        {
            lang = 4;
            break;
        }
    }

    return lang;
}
